import{_ as t,c as a,o,ah as s}from"./chunks/framework.BTxH4YSb.js";const h=JSON.parse('{"title":"Options","description":"","frontmatter":{},"headers":[],"relativePath":"developer/options.md","filePath":"developer/options.md","lastUpdated":1787562627000}'),d={name:"developer/options.md"};function i(c,e,n,l,r,u){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h1><p>Options you can use to customise the AireFrame experience.</p><h2 id="headless-mode" tabindex="-1">Headless Mode <a class="header-anchor" href="#headless-mode" aria-label="Permalink to &quot;Headless Mode&quot;">​</a></h2><p>AireFrame can be rendered in a &#39;headless&#39; mode where the navigation components are not rendered. This may be useful when embededding AireFrame inside another site for example.</p><p>To use headless mode, all you need to do is add the query parameter <code>?headless=true</code> to the URL.</p><p>You can also control how the subject banner is displayed by using the <code>subjectBanner</code> query parameter. The options are:</p><ul><li><code>hidden</code>: No subject banner is displayed.</li><li><code>collapsed</code>: The subject banner is displayed in a collapsed state, showing only the subject&#39;s primary field value.</li><li><code>expanded</code>: The subject banner is displayed in an expanded state, showing all of the subject&#39;s custom field values.</li></ul><div class="info custom-block"><p class="custom-block-title">Example</p><p><code>?headless=true&amp;subjectBanner=collapsed</code></p></div><h2 id="subject-launch" tabindex="-1">Subject Launch <a class="header-anchor" href="#subject-launch" aria-label="Permalink to &quot;Subject Launch&quot;">​</a></h2><p>You can launch directly into the subject record page by using the subject launch feature. This allows you to specify a <code>unique</code> custom field key and value to launch directly into the subject record page for the subject that matches that custom field key and value.</p><p>To use this feature, simply navigate to <code>https://frame.aireinnovate.com/subject-launcher/&lt;custom_field_key&gt;/&lt;custom_field_value&gt;</code></p><div class="info custom-block"><p class="custom-block-title">Note</p><p>The custom field must be set to <code>unique</code> in the configuration for the specified custom field key in order for this feature to work.</p></div>',12)])])}const m=t(d,[["render",i]]);export{h as __pageData,m as default};
